set -eu
python - <<'PY'
import csv, math
from pathlib import Path

inputs = {
    'iron': '$(inputs.iron_table.path)',
    'innate': '$(inputs.innate_table.path)',
}
outputs = {
    'iron': ('iron_foreground.tsv', 'iron_background.tsv'),
    'innate': ('innate_foreground.tsv', 'innate_background.tsv'),
}
summary = []

def parse_float(value):
    if value is None:
        return None
    text = value.strip()
    if text == '' or text.upper() == 'NA' or text.lower() == 'nan':
        return None
    try:
        val = float(text)
    except ValueError:
        return None
    if math.isnan(val):
        return None
    return val

for label, path in inputs.items():
    foreground = []
    background = []
    total = 0
    with open(path, newline='') as handle:
        reader = csv.DictReader(handle, delimiter='\t')
        required = {'rowname', 'log2FoldChange', 'padj'}
        missing = required.difference(reader.fieldnames or [])
        if missing:
            raise SystemExit(f"{label}: missing required columns: {sorted(missing)}")
        for row in reader:
            gene = (row.get('rowname') or '').strip()
            if not gene:
                continue
            total += 1
            background.append(gene)
            lfc = parse_float(row.get('log2FoldChange'))
            padj = parse_float(row.get('padj'))
            if lfc is not None and padj is not None and abs(lfc) > 1.5 and padj < 0.05:
                foreground.append(gene)
    fg_path, bg_path = outputs[label]
    for out_path, genes in [(fg_path, foreground), (bg_path, background)]:
        with open(out_path, 'w', newline='') as out:
            out.write('gene\n')
            for gene in genes:
                out.write(gene + '\n')
    summary.append((label, total, len(background), len(foreground)))

with open('filter_summary.tsv', 'w', newline='') as out:
    out.write('contrast\ttotal_rows\tbackground_genes\tforeground_genes\n')
    for row in summary:
        out.write('\t'.join(map(str, row)) + '\n')
PY

